import sys

def min_actions_to_sort(n, p):
    sorted_p = sorted(range(1, n+1))
    actions = 0
    start, end = 0, n-1

    for i in range(n):
        if p[i] != sorted_p[i]:
            if p.index(sorted_p[i], start, end+1) - i > end - p.index(sorted_p[i], start, end+1):
                actions += 1
                end = p.index(sorted_p[i], start, end+1)
            else:
                actions += 1
                start = p.index(sorted_p[i], start, end+1)

    return actions

if __name__ == "__main__":
    n = int(input())
    p = list(map(int, input().split()))
    print(min_actions_to_sort(n, p))

def min_moves_to_sort_train():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    # Find the longest increasing subsequence (LIS) in the sequence p
    def lis_length(seq):
        if not seq:
            return 0
        lis = [seq[0]]
        for i in range(1, len(seq)):
            if seq[i] > lis[-1]:
                lis.append(seq[i])
            else:
                # Find the right position to replace
                low, high = 0, len(lis) - 1
                while low < high:
                    mid = (low + high) // 2
                    if lis[mid] < seq[i]:
                        low = mid + 1
                    else:
                        high = mid
                lis[low] = seq[i]
        return len(lis)

    # The number of actions is the number of cars minus the length of the LIS
    result = n - lis_length(p)

    print(result)
